def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def bands(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_bands = bands(h, divider_rows)
    col_bands = bands(w, divider_cols)

    # Use the panel containing the most non-background cells as the motif.
    best_panel = None
    best_count = -1
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            count = sum(v != background for row in panel for v in row)
            if count > best_count:
                best_count = count
                best_panel = panel

    out = [row[:] for row in grid]
    if best_panel is None:
        return out

    ph, pw = len(best_panel), len(best_panel[0])
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1 - r0 == ph and c1 - c0 == pw:
                for dr in range(ph):
                    for dc in range(pw):
                        out[r0 + dr][c0 + dc] = best_panel[dr][dc]

    return out
